from django.test import TestCase
from core.models import LawDocument as UserUpload
from legal_kb.models import Document

class UserUploadIsolationTest(TestCase):
    def test_user_uploads_remain_separate(self):
        user_upload = UserUpload.objects.create(
            title="Test User Document",
            content="This is a user-uploaded document",
            uploaded_by_id=1
        )
        
        # Verify it doesn't appear in legal knowledge base
        legal_docs = Document.objects.filter(source_url__icontains="user_upload")
        self.assertEqual(len(legal_docs), 0)
        
        # Verify it's in user upload collection
        user_docs = UserUpload.objects.filter(title="Test User Document")
        self.assertEqual(len(user_docs), 1)

