class ApprovalWorkflowTest(TestCase):
    def test_document_needs_approval_before_indexing(self):
        doc = Document.objects.create(
            source_url="https://example.gov.gh/act123",
            category=DocumentCategory.LEGISLATION,
            document_type="Act",
            license_category=LicenseCategory.PUBLIC_DOMAIN
        )
        
        # Unapproved document should not be indexed
        indexed_docs = Document.objects.filter(approval_status=True)
        self.assertEqual(len(indexed_docs), 0)
        
        # After approval
        doc.approval_status = True
        doc.approved_by_id = 1
        doc.save()
        
        indexed_docs = Document.objects.filter(approval_status=True)
        self.assertEqual(len(indexed_docs), 1)

