# legal_kb/pipeline/citation_extractor.py
import spacy
from .models import Citation

# Load spaCy model
nlp = spacy.load("en_core_web_sm")

def extract_citations(text):
    doc = nlp(text)
    citations = []
    
    # Pattern matching for constitutional articles
    for ent in doc.ents:
        if ent.label_ == "ORDINAL" and "Article" in ent.text:
            citations.append({
                "type": "article",
                "reference": ent.text
            })
    
    # Regex for section numbers
    section_matches = re.finditer(r'Section (\d+)(?:\([^)]+\))?', text)
    for match in section_matches:
        citations.append({
            "type": "section",
            "reference": f"Section {match.group(1)}{match.group(2) or ''}"
        })
    
    # Case name pattern
    case_matches = re.finditer(r'([A-Z][a-z]+ v [A-Z][a-z]+) \d{4} ([A-Z]+)', text)
    for match in case_matches:
        citations.append({
            "type": "case",
            "reference": f"{match.group(1)} {match.group(2)}"
        })
    
    return citations

# legal_kb/pipeline/version_control.py
from .models import Version

def handle_version(document, new_content):
    existing_versions = Version.objects.filter(document=document)
    
    # Check for duplicate
    new_hash = document.calculate_hash(new_content)
    if existing_versions.filter(content_hash=new_hash).exists():
        return False, "Duplicate content detected"
    
    # Create new version
    new_version = Version.objects.create(
        document=document,
        content_hash=new_hash,
        effective_date=document.effective_date,
        storage_path=f"proxmox_b/legal/{document.id}_{new_hash}.pdf"
    )
    
    # Mark previous as superseded
    if existing_versions.filter(is_current=True).exists():
        current = existing_versions.get(is_current=True)
        current.is_current = False
        current.superseded_by = new_version
        current.save()
    
    new_version.is_current = True
    new_version.save()
    return True, "Version created successfully"

# legal_kb/tests/test_citation_handling.py
class CitationTest(TestCase):
    def test_citations_are_properly_extracted(self):
        test_text = """
        Under Article 12(4) of the Constitution, every citizen shall have the right 
        to freedom of speech. This was affirmed in the case of Nkrumah v Parliament 
        2020 SC. Section 5(3) of the Labour Act 2003 further elaborates on these rights.
        """
        
        citations = extract_citations(test_text)
        self.assertEqual(len(citations), 3)
        
        expected = [
            {"type": "article", "reference": "Article 12(4)"},
            {"type": "case", "reference": "Nkrumah v Parliament 2020 SC"},
            {"type": "section", "reference": "Section 5(3)"}
        ]
        
        for i, citation in enumerate(citations):
            self.assertEqual(citation["type"], expected[i]["type"])
            self.assertEqual(citation["reference"], expected[i]["reference"])

