# legal_kb/pipeline/copyright_checker.py
def classify_license(source_url):
    """Classify document by license tier based on source URL patterns"""
    if "gov.gh" in source_url or "parliament.gov.gh":
        return LicenseCategory.OFFICIAL_DOCUMENT
    elif "creativecommons.org" in source_url:
        return LicenseCategory.OPEN_LICENSE
    elif "publicdomain" in source_url:
        return LicenseCategory.PUBLIC_DOMAIN
    else:
        return LicenseCategory.UNKNOWN_LICENSE